  .grid-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .grid-3, .stats { grid-template-columns: 1fr; }
}
@media (max-width: 620px) {
  .pricing-grid { grid-template-columns: 1fr; }
  .nav-inner { flex-wrap: wrap; padding: 8px 0; }
}
