.small { color: var(--muted); font-size: .95rem; }
.feature-list { margin: 12px 0 0; padding-left: 18px; color: var(--muted); }
.hidden-features { display: none; margin-top: 8px; }
.hidden-features.open { display: block; }

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: 14px;
}
table {
  border-collapse: collapse;
  width: 100%;
  min-width: 760px;
  background: #fff;
}
th, td {
  border-bottom: 1px solid var(--border);
  padding: 12px;
  text-align: left;
}
th { background: #f8f9ff; }

.faq-item {
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px 14px;
  background: #fff;
}
.faq-q {
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
