.cookie-row { display: flex; gap: 12px; align-items: center; justify-content: space-between; flex-wrap: wrap; }
.cookie-actions { display: flex; gap: 8px; flex-wrap: wrap; }

.modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.36);
